/* @autogenerated */
import { TenantRepository } from 'app/features/identity/tenant/repository/tenant-repository.service';
import { User } from 'app/features/identity/user/model/user.model';
import { USER_EXCEL_SENSITIVE, USER_EXCEL_COLUMNS } from 'app/features/identity/user/model/user-excel-columns';
import { normalizeHeader } from 'app/shared/toolkit/entity-import/column-match';
import { take, map } from 'rxjs';
import { UserRepository } from 'app/features/identity/user/repository/user-repository.service';
import { BaseImportAction } from 'app/shared/toolkit/action/base-import-action';
import { ImportDefinition } from 'app/shared/toolkit/entity-import/entity-import.model';
import { Component, inject } from '@angular/core';

/** Candidatos que pide cada búsqueda: el filtro puede no ser exacto y se comprueba aquí. */
const LOOKUP_LIMIT = 50;

@Component({
  selector: 'user-view-import-action',
  standalone: false,
  templateUrl: './user-view-import-action.component.html',
})
export class UserViewImportActionComponent extends BaseImportAction<User> {
  protected readonly scope = 'identity/user';
  protected readonly repository = inject(UserRepository);
  private readonly tenantRepository = inject(TenantRepository);

  readonly definition: ImportDefinition<User> = {
    storageKey: 'identity.user',
    scope: this.scope,
    // Clave natural (índice único del modelo): una fila con los mismos valores actualiza el elemento
    keys: ['tenant', 'name'],
    columns: USER_EXCEL_COLUMNS,
    sensitive: USER_EXCEL_SENSITIVE,
    // Campos que el backend solo cambia con sus acciones: se aplican tras crear o actualizar
    actions: {
      approvalStatus: [
        { name: 'accept', value: 'accepted', run: (item) => this.repository.accept(item.uid) },
        { name: 'reject', value: 'rejected', run: (item) => this.repository.reject(item.uid) },
      ],
      enabled: [
        { name: 'disable', value: false, run: (item) => this.repository.disable(item.uid) },
        { name: 'enable', value: true, run: (item) => this.repository.enable(item.uid) },
      ],
    },
    references: {
      tenant: {
        resolve: (text) =>
          this.tenantRepository.values({ search: text, limit: LOOKUP_LIMIT }).pipe(
            take(1),
            map((found) => {
              const wanted = normalizeHeader(text);
              const one = found.find(
                (candidate) => candidate.uid === text || normalizeHeader(candidate.name) === wanted,
              );
              return one ? { $ref: one.uid } : null;
            }),
          ),
      },
    },
    defaults: () => ({
      emailVerified: false,
      enabled: true,
      approvalStatus: 'accepted',
      temporalPassword: false,
      useSecondFactors: false,
    }),
    display: (values) => String(values.name ?? ''),
    target: {
      acl: () => this.repository.checkAcl(),
      find: (values) =>
        this.repository
          .values({
            tenant: values.tenant?.$ref ? [values.tenant.$ref] : undefined,
            name: values.name,
            limit: LOOKUP_LIMIT,
          })
          .pipe(
            take(1),
            map((found) =>
              found.filter(
                (item) =>
                  (!values.tenant?.$ref || item.tenant?.$ref === values.tenant.$ref) && item.name === values.name,
              ),
            ),
          ),
      add: (item) => this.repository.add(item),
      update: (item) => this.repository.update(item),
    },
  };
}
